INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('fdd9949c-066f-42b3-afa4-7e63b02aa5dd', 'a4893b2e-8257-48d4-9570-e8dfcaccace7', 'A 22-year-old female patient A private prescription for Morphine sulfate 10 mg tablets (Schedule 2 CD) is presented at a community pharmacy. The prescription is dated 32 days ago and specifies total quantity as 56 tablets without words and figures. (Case Ref: PHARMACY-LAW-0911). Relevant physiological and medication history have been reviewed.', 'Can the pharmacist legally dispense this prescription?', NULL, NULL, NULL, NULL, 1, NULL, 1789655696, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('6166246c-843e-4b60-b60b-d2dc61c2ab5c', 'a4893b2e-8257-48d4-9570-e8dfcaccace7', 'A', 'No, because Schedule 2 prescriptions are valid for only 28 days from date of signing and require total quantity in words and figures', 1, 'Correct. Schedule 2, 3, and 4 Controlled Drug prescriptions are legally valid for 28 days only. Schedule 2 and 3 prescriptions mandate total quantity in both words and figures.', 0, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('e0c89152-862a-457f-8257-eb04ab16fc79', 'a4893b2e-8257-48d4-9570-e8dfcaccace7', 'B', 'Dispense half the quantity and request an amended prescription for the balance', 0, 'Illegal. An invalid CD prescription cannot be partially dispensed.', 1, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('1c546d54-87dd-46c9-b93d-400aeaf56a18', 'a4893b2e-8257-48d4-9570-e8dfcaccace7', 'C', 'Dispense the full supply and annotate the words and figures manually without prescriber amendment', 0, 'Illegal for total quantity. Pharmacists may only amend minor spelling/typographical errors or words/figures if omitted in specific limited home office circular exemptions.', 2, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('e1e40e3f-9f90-4bff-83cd-d3de35c6344c', 'a4893b2e-8257-48d4-9570-e8dfcaccace7', 'D', 'Accept validity for 6 months as per standard prescription rules', 0, 'Standard POMs are valid for 6 months, but Controlled Drugs (Schedule 2-4) expire at 28 days.', 3, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('81d5ab7b-0ca3-4c37-8dca-38c6d0d3a2ad', 'a4893b2e-8257-48d4-9570-e8dfcaccace7', 'E', 'Dispense under emergency supply regulations', 0, 'Schedule 2 and 3 CDs cannot be supplied under emergency supply regulations at patient request (except phenobarbital for epilepsy).', 4, 1789655696);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('62c91d9b-d917-48fd-ac9a-e48f4ea260ad', 'a4893b2e-8257-48d4-9570-e8dfcaccace7', 'Schedule 2 and 3 CD prescriptions are valid for 28 days and must contain quantity in both words and figures.', 'Installment prescriptions (FP10MDA) must have the first installment dispensed within 28 days of signing. Reference: Misuse of Drugs Regulations 2001 & MEP 46.', 'Misuse of Drugs Regulations 2001 & MEP 46', 1789655696, 1789655696);
INSERT INTO question_governance (id, question_id, clinical_approved_at, educational_approved_at, copy_editor_approved_at, approved_at, conflict_of_interest, created_at, updated_at) VALUES ('475ec4fc-7af5-4699-b549-a6a41e9ea336', 'a4893b2e-8257-48d4-9570-e8dfcaccace7', 1789655696, 1789655696, 1789655696, 1789655696, 0, 1789655696, 1789655696);
